O = sun-crest
p = pressure-plate
_ = pit
e = earth
t = tunnel
~ = steps
# = wall-top
F = wall-face
C = wall-crest
N = wall-niche
B = wall-base
% = earth-top
E = earth-face
$ = coins
r = rubble
d = debris
a = darts
b = bones
c = cobweb
k = cobweb-ne

